#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <unordered_map>

// The counting operator new from the lesson on allocations.
long g_allocs = 0;
long g_bytes = 0;

void* operator new(std::size_t size) {
    ++g_allocs;
    g_bytes += size;
    if (void* p = std::malloc(size)) {
        return p;
    }
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

void load(int orders, bool reserve_first) {
    const long allocs_before = g_allocs;
    const long bytes_before = g_bytes;
    std::unordered_map<std::int64_t, int> qty_by_id;
    if (reserve_first) {
        qty_by_id.reserve(orders);
    }
    int rehashes = 0;
    std::size_t buckets = qty_by_id.bucket_count();
    for (int i = 0; i < orders; ++i) {
        qty_by_id[700000 + i] = 100;
        if (qty_by_id.bucket_count() != buckets) {
            buckets = qty_by_id.bucket_count();
            ++rehashes;
            std::cout << "  size " << qty_by_id.size() << ": " << buckets << " buckets\n";
        }
    }
    std::cout << (reserve_first ? "reserve" : "grow") << ": " << rehashes << " rehashes, "
              << g_allocs - allocs_before << " allocations, " << g_bytes - bytes_before
              << " bytes, " << buckets << " buckets\n";
}

int main() {
    load(100, false);
    load(100, true);
    return 0;
}

