#include <cstddef>
#include <functional>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

long g_compares = 0;

struct QuoteKey {
    std::string symbol;
    int venue;
};

bool operator==(const QuoteKey& a, const QuoteKey& b) {
    ++g_compares;
    return a.venue == b.venue && a.symbol == b.symbol;
}

namespace std {
template <>
struct hash<QuoteKey> {
    size_t operator()(const QuoteKey& k) const noexcept {
        size_t h = hash<string>{}(k.symbol);
        h ^= hash<int>{}(k.venue) + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2);
        return h;
    }
};
}  // namespace std

struct SymbolOnly {  // forgets the venue
    std::size_t operator()(const QuoteKey& k) const noexcept {
        return std::hash<std::string>{}(k.symbol);
    }
};

struct CharSum {  // adds up the letters
    std::size_t operator()(const QuoteKey& k) const noexcept {
        std::size_t h = k.venue;
        for (char c : k.symbol) {
            h += c;
        }
        return h;
    }
};

template <typename Hash>
void test(const char* name, const std::vector<QuoteKey>& keys) {
    std::unordered_map<QuoteKey, int, Hash> book;
    for (std::size_t i = 0; i < keys.size(); ++i) {
        book[keys[i]] = static_cast<int>(i);
    }
    std::size_t largest = 0;
    for (std::size_t b = 0; b < book.bucket_count(); ++b) {
        largest = book.bucket_size(b) > largest ? book.bucket_size(b) : largest;
    }
    g_compares = 0;
    long check = 0;
    for (const QuoteKey& k : keys) {
        check += book.find(k)->second;
    }
    std::cout << name << ": " << g_compares << " compares for " << keys.size()
              << " lookups, largest bucket " << largest << ", checksum " << check << '\n';
}

int main() {
    std::vector<QuoteKey> keys;
    for (int i = 0; i < 400; ++i) {
        const std::string symbol = {char('A' + i / 26), char('A' + i % 26), char('A' + i * 7 % 26)};
        for (int venue = 0; venue < 5; ++venue) {
            keys.push_back({symbol, venue});
        }
    }
    test<SymbolOnly>("symbol only", keys);
    test<CharSum>("char sum", keys);
    test<std::hash<QuoteKey>>("combined", keys);
    return 0;
}

