#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <new>
#include <string>
#include <vector>

// The counting operator new from the lesson on allocations.
long g_allocs = 0;
void* operator new(std::size_t size) {
    ++g_allocs;
    if (void* p = std::malloc(size)) return p;
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

std::uint64_t pack(const std::string& s) {  // up to 8 chars in one integer
    std::uint64_t key = 0;
    std::memcpy(&key, s.data(), s.size() < 8 ? s.size() : 8);
    return key;
}

std::uint64_t mix(std::uint64_t k) {
    k ^= k >> 33;
    k *= 0xff51afd7ed558ccdULL;
    k ^= k >> 33;
    return k;
}

struct Slot { std::uint64_t key = 0; int id = -1; };  // key 0 means empty

struct SymbolMap {
    std::vector<Slot> slots = std::vector<Slot>(1024);  // a power of two
    static constexpr std::uint64_t mask = 1023;
    bool use_mix = true;
    long probes = 0;

    std::uint64_t home(std::uint64_t key) const { return (use_mix ? mix(key) : key) & mask; }

    void insert(std::uint64_t key, int id) {
        std::uint64_t i = home(key);
        while (slots[i].key != 0 && slots[i].key != key) {
            i = (i + 1) & mask;  // linear probing: try the next slot
        }
        slots[i] = {key, id};
    }

    int find(std::uint64_t key) {
        for (std::uint64_t i = home(key);; i = (i + 1) & mask) {
            ++probes;
            if (slots[i].key == key) return slots[i].id;
            if (slots[i].key == 0) return -1;
        }
    }
};

int main() {
    std::vector<std::string> symbols = {"AAPL", "AMZN", "MSFT", "NVDA"};
    for (int i = 0; i < 496; ++i) {
        symbols.push_back({char('A' + i / 26 % 26), char('A' + i % 26), char('A' + i * 7 % 26)});
    }
    for (bool mixed : {false, true}) {
        const long allocs_before = g_allocs;
        SymbolMap map;
        map.use_mix = mixed;
        for (std::size_t i = 0; i < symbols.size(); ++i) {
            map.insert(pack(symbols[i]), static_cast<int>(i));
        }
        std::cout << (mixed ? "mix" : "identity") << ": " << g_allocs - allocs_before << " allocation for 500 inserts, ";
        for (const std::string& s : symbols) {
            map.find(pack(s));
        }
        std::cout << map.probes << " probes for 500 lookups, MSFT -> " << map.find(pack("MSFT"))
                  << ", TSLA -> " << map.find(pack("TSLA")) << '\n';
    }
    return 0;
}

