#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <map>
#include <new>
#include <vector>

// The counting operator new from the lesson on allocations.
long g_allocs = 0;
long g_bytes = 0;
void* operator new(std::size_t size) {
    ++g_allocs;
    g_bytes += size;
    if (void* p = std::malloc(size)) return p;
    throw std::bad_alloc();
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

int open_interest(int strike) {  // made-up data
    return strike % 7 * 100 + 50;
}

int main() {
    long allocs = g_allocs;
    long bytes = g_bytes;
    std::map<int, int> oi_by_strike;
    for (int k = 150; k <= 250; k += 5) {
        oi_by_strike[k] = open_interest(k);
    }
    std::cout << "map: " << oi_by_strike.size() << " strikes, " << g_allocs - allocs << " allocations, "
              << g_bytes - bytes << " bytes\n";

    allocs = g_allocs;
    bytes = g_bytes;
    std::vector<int> strikes;  // sorted, with open interest in a parallel vector
    std::vector<int> oi;
    strikes.reserve(21);
    oi.reserve(21);
    for (int k = 150; k <= 250; k += 5) {
        strikes.push_back(k);
        oi.push_back(open_interest(k));
    }
    std::cout << "vectors: " << strikes.size() << " strikes, " << g_allocs - allocs << " allocations, "
              << g_bytes - bytes << " bytes\n";

    const int lo = 183;
    const int hi = 205;
    long total = 0;
    std::cout << "map " << lo << " to " << hi << ":";
    for (auto it = oi_by_strike.lower_bound(lo); it != oi_by_strike.upper_bound(hi); ++it) {
