#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> strikes(n);
    for (int& k : strikes) {
        std::cin >> k;
    }
    std::sort(strikes.begin(), strikes.end());

    int spot = 0;
    while (std::cin >> spot) {
        auto it = std::lower_bound(strikes.begin(), strikes.end(), spot);
        int nearest = 0;
        if (it == strikes.end()) {
            nearest = strikes.back();
        } else if (it == strikes.begin()) {
            nearest = *it;
        } else {
            const int above = *it;
            const int below = *(it - 1);
            nearest = (spot - below <= above - spot) ? below : above;
        }
        std::cout << "spot " << spot << " -> strike " << nearest << '\n';
    }
    return 0;
}
